CREATE OR REPLACE FUNCTION public.shard_ledger_reconcile()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with s as (
    select p.id, p.shard_balance, coalesce(sum(l.amount), 0)::bigint as ledger
